<script setup lang="ts">import{reactive,onMounted}from 'vue';import{useRouter}from 'vue-router';import{samples,loadBatches}from '../stores/samples';import{chains,loadChains}from '../stores/chains';import{createChain}from '../api/chains';import{canEdit}from '../stores/auth';import{useTask}from '../hooks/useTask';import{chainStatusLabels}from '../constants/enums';import{number}from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import BatchSelect from '../components/BatchSelect.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';
const router=useRouter();const{error,busy,execute}=useTask();
const form=reactive({name:'城区逐月 · 链式比较',description:'冻结共同目标与样本版本，逐月校准并分解构成/时长贡献。',tolerance:.0001,max_iterations:500,cap_ratio:12,pickers:[{batch_id:1,month_label:'10月'},{batch_id:2,month_label:'11月'}]});
const refresh=()=>execute(async()=>{await Promise.all([loadBatches(),loadChains()])});
const addRow=()=>form.pickers.push({batch_id:samples.batches[0]?.id||1,month_label:(form.pickers.length+10)+'月'});
const removeRow=(i:number)=>form.pickers.splice(i,1);
const submit=()=>execute(async()=>{
  const detail=await createChain({name:form.name,description:form.description,tolerance:form.tolerance,max_iterations:form.max_iterations,cap_ratio:form.cap_ratio,batches:form.pickers});
  await router.push('/chains/'+detail.id);
});
onMounted(refresh);
</script><template><PageHeading index="05" title="逐月之间，先冻结同一把尺" subtitle="为一组批次冻结共同目标与样本版本，逐月校准后把相邻月份差值分解为样本构成与时长贡献。"/><ErrorNotice :message="error" @retry="refresh"/><div class="workbench"><form v-if="canEdit" @submit.prevent="submit"><h2>建立链式比较组</h2><label>研究名称<input v-model="form.name" required minlength="2" maxlength="100"/></label><label>说明<input v-model="form.description" maxlength="500"/></label><div v-for="(row,i) in form.pickers" :key="i" class="chain-picker"><BatchSelect v-model="row.batch_id" :items="samples.batches"/><label>月份标签<input v-model="row.month_label" required maxlength="20"/></label><button type="button" :disabled="form.pickers.length<=2" @click="removeRow(i)">移除</button></div><button type="button" @click="addRow" :disabled="form.pickers.length>=12">＋ 追加月份</button><div class="form-grid"><label>归一残差容差<input v-model.number="form.tolerance" type="number" min=".000001" max=".05" step=".000001" required/></label><label>最多迭代次数<input v-model.number="form.max_iterations" type="number" min="1" max="2000" required/></label></div><label>权重上限 / 目标平均权重的倍数<input v-model.number="form.cap_ratio" type="number" min="1" max="30" step=".1" required/></label><button class="primary" :disabled="busy">{{busy?'正在排队…':'冻结口径并启动链 →'}}</button></form><aside><p class="eyebrow">CHAIN / FROZEN INPUTS</p><h2>差值里混进的<br>人群构成变化，被拆出来。</h2><p>建组时把首批次的边际目标冻结为全组共同目标，每个批次冻结各自样本快照；之后实时表的改动不再影响已冻结链，显式更正才推进版本。</p><p>相邻月份按 (分区×年龄组×方式) 格做对称分解：构成效应 + 时长效应 ≡ 均值变化，逐格落库并做恒等式对账。</p><p>样本或目标更正只重算受影响链段；整组新结果齐备并原子发布前，已发布版本始终保留可读。</p></aside></div><div class="section-heading"><h2>链式比较组</h2><button @click="refresh">刷新 ↻</button></div><div class="table-wrap"><table><thead><tr><th>比较组</th><th>链状态</th><th>工作版本</th><th>已发布版本</th><th>节点 / 链段</th><th></th></tr></thead><tbody><tr v-for="g in chains.items" :key="g.id"><td><strong>{{g.name}}</strong><small>CHAIN / {{String(g.id).padStart(4,'0')}}</small></td><td><span class="badge" :class="g.status">{{chainStatusLabels[g.status]||g.status}}</span></td><td>v{{g.version}}</td><td>{{g.published_version?('v'+g.published_version):'未发布'}}</td><td>{{number(g.node_count,0)}} / {{number(g.segment_count,0)}}</td><td><RouterLink :to="'/chains/'+g.id">依赖与分解 ↗</RouterLink></td></tr></tbody></table></div></template>
